div.script:
function getProjectGPS() {
    var statusEl = document.getElementById('gps_status');
    if (!navigator.geolocation) {
        statusEl.textContent = '您的瀏覽器不支援 GPS 定位';
        return;
    }
    statusEl.textContent = '正在取得位置...';
    navigator.geolocation.getCurrentPosition(
        function(pos) {
            document.getElementById('project_lat').value = pos.coords.latitude.toFixed(6);
            document.getElementById('project_lng').value = pos.coords.longitude.toFixed(6);
            var locInput = document.getElementById('project_location');
            if (!locInput.value) {
                locInput.value = '(' + pos.coords.latitude.toFixed(6) + ', ' + pos.coords.longitude.toFixed(6) + ')';
            }
            statusEl.textContent = 'GPS 位置已取得';
            statusEl.style.color = 'var(--wb-green)';
        },
        function(err) {
            statusEl.textContent = '無法取得位置';
            statusEl.style.color = 'var(--wb-red)';
        },
        { enableHighAccuracy: true, timeout: 10000 }
    );
}

function getProjectGPS() {
    var statusEl = document.getElementById('gps_status');
    if (!navigator.geolocation) {
        statusEl.textContent = '您的瀏覽器不支援 GPS 定位';
        return;
    }
    statusEl.textContent = '正在取得位置...';
    navigator.geolocation.getCurrentPosition(
        function(pos) {
            document.getElementById('project_lat').value = pos.coords.latitude.toFixed(6);
            document.getElementById('project_lng').value = pos.coords.longitude.toFixed(6);
            statusEl.textContent = 'GPS 位置已取得：' + pos.coords.latitude.toFixed(6) + ', ' + pos.coords.longitude.toFixed(6);
            statusEl.style.color = 'var(--wb-green)';
        },
        function(err) {
            statusEl.textContent = '無法取得位置';
            statusEl.style.color = 'var(--wb-red)';
        },
        { enableHighAccuracy: true, timeout: 10000 }
    );
}

